-- KG Chart U3B3B2: private-media resource-to-object authorization registry.
-- REVIEW-ONLY PROPOSAL. DO NOT APPLY TO PRODUCTION TECHNICAL SUPABASE.
-- No Storage buckets, objects, policies, user grants or clients are modified.
-- Requires prior U1 -> U3B1 -> U3B2 -> U3B3A -> U3B3B1 manual installation.
--
-- A private asset is keyed by a RANDOM UUID, never by the 32-bit text hash
-- used in existing PUBLIC audio. Its eventual Storage key is generated by
-- the trusted Edge Function from asset_id + allowlisted MIME extension.
-- The SQL never creates a public/private bucket or copies/moves any files.
-- Registration is admin-only and starts as 'staged'. Merely inserting a row
-- does NOT authorize distribution. An asset is eligible only when an admin
-- has separately verified an actual staged copy and recorded its SHA256.
BEGIN;
SELECT pg_advisory_xact_lock(hashtext('kg_chart_u3b3b2_private_delivery_v1'));

CREATE TABLE IF NOT EXISTS public.kg_chart_private_media_assets (
  asset_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  source_type text NOT NULL CHECK (
    source_type IN ('word_audio','topic_audio','sentence_audio',
                    'colour_audio','word_image')),
  source_id uuid,
  topic_id text,
  language_code varchar NOT NULL REFERENCES public.kg_chart_languages(code)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  voice text,
  mime_type text NOT NULL,
  expected_native_text text,
  expected_image_filename text,
  classification text NOT NULL DEFAULT 'unknown'
    CHECK (classification IN ('unknown','shared','private_exclusive')),
  state text NOT NULL DEFAULT 'staged'
    CHECK (state IN ('staged','verified','disabled')),
  byte_size bigint CHECK (byte_size>0),
  sha256_hex text CHECK (sha256_hex ~ '^[0-9a-f]{64}$'),
  verified_at timestamptz,
  verifier_receipt_sha256 text
    CHECK (verifier_receipt_sha256 ~ '^[0-9a-f]{64}$'),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT kg_u3b3b2_resource_shape CHECK (
    (source_type='topic_audio' AND source_id IS NULL
      AND nullif(topic_id,'') IS NOT NULL)
    OR (source_type<>'topic_audio' AND source_id IS NOT NULL
      AND topic_id IS NULL)
  ),
  CONSTRAINT kg_u3b3b2_media_shape CHECK (
    (source_type='word_image' AND voice IS NULL
      AND mime_type IN ('image/png','image/jpeg','image/webp','image/gif')
      AND nullif(expected_image_filename,'') IS NOT NULL
      AND expected_native_text IS NULL)
    OR (source_type<>'word_image' AND voice IN ('m','f')
      AND mime_type='audio/mpeg'
      AND nullif(expected_native_text,'') IS NOT NULL
      AND expected_image_filename IS NULL)
  ),
  CONSTRAINT kg_u3b3b2_verified_proof CHECK (
    state<>'verified' OR
    (classification='private_exclusive'
      AND byte_size IS NOT NULL AND sha256_hex IS NOT NULL
      AND verifier_receipt_sha256 IS NOT NULL
      AND verified_at IS NOT NULL)
  ),
  CONSTRAINT kg_u3b3b2_unique_source UNIQUE NULLS NOT DISTINCT
    (source_type,source_id,topic_id,language_code,voice)
);
CREATE INDEX IF NOT EXISTS kg_chart_private_media_assets_lookup
  ON public.kg_chart_private_media_assets(
    source_type,language_code,state,classification);

ALTER TABLE public.kg_chart_private_media_assets ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.kg_chart_private_media_assets
  FROM PUBLIC, anon, authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE
  ON public.kg_chart_private_media_assets TO authenticated,service_role;
DROP POLICY IF EXISTS kg_u3b3b2_admin_only
  ON public.kg_chart_private_media_assets;
CREATE POLICY kg_u3b3b2_admin_only
  ON public.kg_chart_private_media_assets FOR ALL TO authenticated
  USING ((SELECT public.kg_chart_is_admin()))
  WITH CHECK ((SELECT public.kg_chart_is_admin()));

-- Boolean-only SECURITY DEFINER check. It is safe to call through the
-- authenticated PostgREST API because it never returns the object key,
-- source text, recipient list, checksum or metadata. Identity is the
-- signed-in auth.uid() and source privileges are checked per resource.
-- No caller-supplied object path, bucket, user ID or email is accepted.
CREATE OR REPLACE FUNCTION public.kg_chart_u3b3b2_can_media(
  p_asset_id uuid)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = pg_catalog
AS $fn$
DECLARE
  a record;
  v_text text;
  v_filename text;
  v_group text;
  v_colour uuid;
  v_noun uuid;
  v_lang text;
BEGIN
  IF p_asset_id IS NULL OR auth.uid() IS NULL
    OR public.kg_chart_is_allowed() IS DISTINCT FROM true
  THEN RETURN false; END IF;

  SELECT * INTO a FROM public.kg_chart_private_media_assets AS registry
  WHERE registry.asset_id=p_asset_id
    AND registry.state='verified'
    AND registry.classification='private_exclusive'
    AND registry.verified_at IS NOT NULL
    AND registry.sha256_hex IS NOT NULL
    AND registry.verifier_receipt_sha256 IS NOT NULL
    AND registry.byte_size>0;
  IF NOT FOUND OR public.kg_chart_u3b1_can_language(
      a.language_code::text) IS DISTINCT FROM true
  THEN RETURN false; END IF;

  IF a.source_type='word_audio' THEN
    SELECT t.native_text INTO v_text
    FROM public.kg_chart_vocabulary_translations AS t
    WHERE t.vocabulary_id=a.source_id AND t.language_code=a.language_code;
    RETURN v_text IS NOT NULL AND v_text=a.expected_native_text
      AND public.kg_chart_u3b1_can_vocab_translation(
        a.language_code::text,a.source_id) IS TRUE
      AND public.kg_chart_u3b3a_private_vocabulary(
        a.language_code::text,a.source_id) IS TRUE;
  ELSIF a.source_type='topic_audio' THEN
    SELECT t.question_native INTO v_text
    FROM public.kg_chart_topic_translations AS t
    WHERE t.topic_id=a.topic_id AND t.language_code=a.language_code;
    RETURN v_text IS NOT NULL AND v_text=a.expected_native_text
      AND public.kg_chart_u3b1_can_topic(
        a.language_code::text,a.topic_id) IS TRUE
      AND public.kg_chart_u3b3a_private_topic(
        a.language_code::text,a.topic_id) IS TRUE;
  ELSIF a.source_type='sentence_audio' THEN
    SELECT s.native_text,s.group_name,s.language_code
      INTO v_text,v_group,v_lang
    FROM public.kg_chart_sentences AS s WHERE s.id=a.source_id;
    RETURN v_lang IS NOT DISTINCT FROM a.language_code::text
      AND v_text IS NOT NULL AND v_text=a.expected_native_text
      AND public.kg_chart_u3b2_can_sentence(
        a.language_code::text,a.source_id) IS TRUE
      AND public.kg_chart_u3b3a_private_sentence(
        a.language_code::text,v_group) IS TRUE;
  ELSIF a.source_type='colour_audio' THEN
    SELECT c.native_text,c.language_code,c.colour_id,c.noun_id
      INTO v_text,v_lang,v_colour,v_noun
    FROM public.kg_chart_colour_phrases AS c WHERE c.id=a.source_id;
    RETURN v_lang IS NOT DISTINCT FROM a.language_code::text
      AND v_text IS NOT NULL AND v_text=a.expected_native_text
      AND public.kg_chart_u3b1_can_colour_phrase(
        a.language_code::text,v_colour,v_noun) IS TRUE
      AND public.kg_chart_u3b3a_private_colour(
        a.language_code::text,v_colour,v_noun) IS TRUE;
  ELSIF a.source_type='word_image' THEN
    SELECT v.image_filename INTO v_filename
    FROM public.kg_chart_vocabulary AS v WHERE v.id=a.source_id;
    RETURN v_filename IS NOT NULL
      AND v_filename=a.expected_image_filename
      AND public.kg_chart_u3b1_can_vocab_translation(
        a.language_code::text,a.source_id) IS TRUE
      AND public.kg_chart_u3b3a_private_vocabulary(
        a.language_code::text,a.source_id) IS TRUE;
  END IF;
  RETURN false;
END $fn$;

-- A canonical resolver for U3C/U3D clients that know a resource, not an
-- opaque asset UUID. Returns an asset ID only after the same server-side
-- authorization check. No bucket path is leaked and no file is downloaded.
CREATE OR REPLACE FUNCTION public.kg_chart_u3b3b2_my_media_asset(
  p_source_type text,
  p_source_id uuid,
  p_topic_id text,
  p_language text,
  p_voice text
) RETURNS uuid
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path=pg_catalog
AS $fn$
DECLARE v_asset uuid;
BEGIN
  IF auth.uid() IS NULL
    OR public.kg_chart_is_allowed() IS DISTINCT FROM true
    OR p_source_type NOT IN (
      'word_audio','topic_audio','sentence_audio',
      'colour_audio','word_image')
    OR p_language IS NULL OR p_language !~ '^[a-z]{2,3}$'
    OR (
      (p_source_type='word_image' AND p_voice IS NOT NULL)
      OR (p_source_type<>'word_image' AND p_voice NOT IN ('m','f'))
    )
  THEN RETURN NULL; END IF;
  SELECT a.asset_id INTO v_asset
  FROM public.kg_chart_private_media_assets AS a
  WHERE a.source_type=p_source_type
    AND a.source_id IS NOT DISTINCT FROM p_source_id
    AND a.topic_id IS NOT DISTINCT FROM p_topic_id
    AND a.language_code=p_language
    AND a.voice IS NOT DISTINCT FROM p_voice
    AND a.state='verified'
    AND a.classification='private_exclusive';
  IF v_asset IS NULL THEN RETURN NULL; END IF;
  IF public.kg_chart_u3b3b2_can_media(v_asset) IS DISTINCT FROM true
  THEN RETURN NULL; END IF;
  RETURN v_asset;
END $fn$;

REVOKE ALL ON FUNCTION public.kg_chart_u3b3b2_can_media(uuid)
  FROM PUBLIC,anon;
REVOKE ALL ON FUNCTION public.kg_chart_u3b3b2_my_media_asset(
  text,uuid,text,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.kg_chart_u3b3b2_can_media(uuid)
  TO authenticated;
GRANT EXECUTE ON FUNCTION public.kg_chart_u3b3b2_my_media_asset(
  text,uuid,text,text,text) TO authenticated;

-- NEVER make the existing vocabulary-assets bucket private here.
-- This migration creates NO bucket, NO Storage.objects rows, NO copies,
-- NO signed URLs and NO public-path changes. Manual verified staging of
-- private objects is a separate approval-gated, backed-up operation.
COMMIT;
